13	 * read-only Search Console API and writes to our own DB. A human reviews the
14	 * list at /admin/seo and marks rows REVIEWED/ACTIONED/DISMISSED themselves.
15	 * See lib/seo/searchConsole.ts (OAuth + API) and lib/seo/opportunities.ts
16	 * (filtering) — this file is the thin wrapper that ties them to the DB,
17	 * mirroring worker/marketing.ts over lib/marketing/discovery.ts.
18	 */
19	
20	import { db } from "../lib/db";
21	import { getSettingBool, getSettingInt } from "../lib/settings";
22	import { resolveGscAccessToken, markGscSynced } from "../lib/seo/searchConsole";
23	import { fetchStrikingDistanceOpportunities } from "../lib/seo/opportunities";
24	
25	export async function seoOpportunitySweep(): Promise<void> {
26	  // Operator kill-switch. Defaults ON: this sweep only ever reads Google's
27	  // authorized read-only API (webmasters.readonly) and writes to our own DB —
28	  // the same read-only/low-risk class as marketing_monitor_enabled, which also
29	  // defaults ON. A single Setting flip pauses it without a deploy. It is also
30	  // a natural no-op until an admin actually connects Search Console.
31	  if (!(await getSettingBool("seo_monitor_enabled", true))) return;
32	
33	  // Tunable from Settings (see lib/actions-seo.ts / /admin/seo/settings).
34	  const lookbackDays = await getSettingInt("seo_lookback_days", 90);
35	  const minImpressions = await getSettingInt("seo_min_impressions", 15);
36	
37	  let accessToken: string | undefined;
38	  let siteUrl: string | undefined;
39	  try {
40	    const resolved = await resolveGscAccessToken();
41	    accessToken = resolved.accessToken;
42	    siteUrl = resolved.siteUrl;
43	    if (!accessToken || !siteUrl) {
44	      // Not connected yet is the common/expected case — stay quiet. Anything
45	      // else (a stale connection, a resolvable-but-erroring site lookup) is
46	      // worth a log line so an admin investigating a stalled sweep can see it.
47	      if (resolved.error && !/isn't connected/i.test(resolved.error)) {
48	        console.error(`[seo] ${resolved.error}`);
49	      }
50	      return;
51	    }
52	  } catch (e) {
53	    console.error("[seo] token resolve error", e);
54	    return;
55	  }
56	
57	  let opportunities;
58	  try {
59	    const result = await fetchStrikingDistanceOpportunities({ accessToken, siteUrl, lookbackDays, minImpressions });
60	    opportunities = result.opportunities;
61	    if (!opportunities) {
62	      console.error(`[seo] searchAnalytics query failed: ${result.error}`);
63	      return;
64	    }
65	  } catch (e) {
66	    console.error("[seo] searchAnalytics query error", e);
67	    return;
68	  }
69	
70	  const now = new Date();
71	  let upserted = 0;
72	  for (const o of opportunities) {
73	    // Prisma's compound-unique lookup can't match a NULL `page` (Postgres
74	    // treats every NULL as distinct, so `{query, page: null}` would never
75	    // find an existing row and each sweep would insert a fresh duplicate).
76	    // Coerce to "" for the identity we upsert on — in practice GSC always
77	    // returns a real page string for the query+page dimension pair anyway;
78	    // the column stays nullable per the schema for any future caller that
79	    // queries by `query` alone.
80	    const page = o.page ?? "";
81	    try {
82	      await db.seoOpportunity.upsert({
83	        where: { query_page: { query: o.query, page } },
84	        update: {
85	          impressions: o.impressions,
86	          clicks: o.clicks,
87	          ctr: o.ctr,
88	          position: o.position,
89	          lastSeenAt: now,
90	        },
91	        create: {
92	          query: o.query,
93	          page,
94	          impressions: o.impressions,
95	          clicks: o.clicks,
96	          ctr: o.ctr,
97	          position: o.position,
98	          firstSeenAt: now,
99	          lastSeenAt: now,
100	        },
101	      });
102	      upserted++;
103	    } catch (e) {
104	      console.error("[seo] opportunity upsert error", e);
105	    }
106	  }
107	
108	  await markGscSynced().catch(() => {});
109	  if (upserted > 0) {
110	    console.log(`[seo] upserted ${upserted} striking-distance opportunit${upserted === 1 ? "y" : "ies"}`);
111	  }
112	}
113

