      {!conn.connected && (
        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
          <p className="text-sm font-semibold text-amber-200">Google Search Console isn&apos;t connected yet.</p>
          <p className="mt-1 text-xs text-slate-400">
            Connect it on the{" "}
            <Link href="/admin/seo/settings" className="text-brand-300 underline">
              Settings
            </Link>{" "}
            tab to start pulling opportunities.
          </p>
        </div>
      )}

#!/usr/bin/env node
/**
 * blog-upgrade.mjs — retroactively bring old blog posts up to the new editorial
 * template's expectations. For each targeted post it, idempotently:
 *
 *   1. STRIPS EMOJI from title / excerpt / body / SEO fields (the new renderer
 *      uses line-icons, never emoji — components/marketing/icons.tsx).
 *   2. ENSURES A COVER IMAGE — if the post has no coverImage, assigns the
 *      most topic-relevant screenshot from public/blog/screenshots (same keyword
 *      → image map as scripts/blog-image-backfill.mjs).
 *   3. EMBEDS TOPIC-RELEVANT INLINE IMAGES — replaces any {{SCREENSHOT}}
 *      sentinels, or (if the post has none and no image yet) injects up to
 *      --max-inline distinct screenshots after its headings.
 *
 * IDEMPOTENT: re-running makes no further changes — no emoji left to strip, a
 * cover already set is kept, and posts that already carry a /blog/screenshots
 * image are not re-injected. A post is only written when something actually
 * changed.
 *
 * SAFE BY DEFAULT: this is a DRY RUN unless you pass --apply. Even with --apply
 * it refuses to write unless you also pass --yes (or set ALLOW_APPLY=1), and it
 * prints the target database host first so a prod write is never a surprise.
 * Writing to the production DB is a gated action — run the dry run, review the
 * sample diffs, then have the main session apply it in reviewed batches.
 *
 * USAGE
 *   node scripts/blog-upgrade.mjs                       # dry run, all published posts
 *   node scripts/blog-upgrade.mjs --slug my-post-slug   # dry run, one post
 *   node scripts/blog-upgrade.mjs --tag seobatch        # dry run, the SEO batch
 *   node scripts/blog-upgrade.mjs --limit 50 --samples 5
 *   node scripts/blog-upgrade.mjs --tag seobatch --apply --yes   # WRITE (gated)
 *
 * FLAGS
 *   --slug <slug>     target a single post
 *   --tag <tag>       target posts carrying <tag> (e.g. seobatch)
 *   (default)         all published posts
 *   --limit <n>       cap how many posts are processed (0 = no cap)
 *   --samples <n>     how many before/after examples to print in full (default 3)
 *   --max-inline <n>  max inline images to inject when a post has none (default 2)
 *   --no-inline       skip inline-image injection entirely
 *   --apply           actually write changes (otherwise dry run)
 *   --yes             required alongside --apply to confirm writes
 */

import { db } from "./blog-seed-lib.mjs";

/* ── args ─────────────────────────────────────────────────────────────────── */
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const val = (name, def = null) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] && !args[i + 1].startsWith("--") ? args[i + 1] : def;
};
const SLUG = val("slug");
const TAG = val("tag");
const LIMIT = parseInt(val("limit", "0"), 10) || 0;
const SAMPLES = parseInt(val("samples", "3"), 10);
const MAX_INLINE = has("no-inline") ? 0 : parseInt(val("max-inline", "2"), 10);
const APPLY = has("apply");
const CONFIRM = has("yes") || process.env.ALLOW_APPLY === "1";

